PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorLatch : BOOL := FALSE;
    EStopTimer : TON;
END_VAR

EStopTimer(IN := NOT EStop, PT := T#5s);

IF NOT EStop THEN
    MotorLatch := FALSE;
END_IF;

IF EStopTimer.Q AND Start AND NOT Stop THEN
    MotorLatch := TRUE;
ELSIF EStopTimer.Q AND Stop THEN
    MotorLatch := FALSE;
END_IF;

Motor := MotorLatch;
END_PROGRAM

