ELSIF Stop THEN
    Motor := FALSE;
    MotorOn := FALSE;
ELSIF Start AND NOT MotorOn THEN
    Motor := TRUE;
    MotorOn := TRUE;
END_IF;

Motor := Motor AND EStop;

