PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL := FALSE;
    ValveOut : BOOL := FALSE;
END_VAR

VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

CASE Level OF
    0 .. LowLimit:
        PumpIn := TRUE;
        ValveOut := FALSE;
    LowLimit + 1 .. HighLimit - 1:
        PumpIn := FALSE;
        ValveOut := FALSE;
    HighLimit .. 100:
        PumpIn := FALSE;
        ValveOut := TRUE;
END_CASE;

IF Level >= HighLimit THEN
    PumpTimer(IN := TRUE, PT := T#1s);
ELSE
    PumpTimer(IN := FALSE);
END_IF;

IF PumpTimer.Q THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    PumpInTimer(IN := TRUE, PT := T#1s);
ELSEIF Level >= HighLimit THEN
    PumpIn := FALSE;
    PumpInTimer(IN := FALSE);
    ValveOut := TRUE;
    ValveOutTimer(IN := TRUE, PT := T#1s);
ELSE
    PumpIn := FALSE;
    PumpInTimer(IN := FALSE);
    ValveOut := FALSE;
    ValveOutTimer(IN := FALSE);
END_IF;

PumpIn := NOT (PumpIn AND ValveOut);
ValveOut := (Level >= HighLimit);

END_PROGRAM

