PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_T : TON;
    DoorB_T : TON;
    Last_OpenA_Cmd : BOOL := FALSE;
    Last_OpenB_Cmd : BOOL := FALSE;
END_VAR

DoorA_T(IN := OpenA_Cmd AND NOT OpenB_Cmd, PT := T#1s);
DoorB_T(IN := OpenB_Cmd AND NOT OpenA_Cmd, PT := T#1s);

IF OpenA_Cmd AND OpenB_Cmd THEN
    IF NOT Last_OpenA_Cmd THEN
        DoorA_T(IN := TRUE, PT := T#1s);
        DoorB_T(IN := FALSE, PT := T#0s);
    ELSIF NOT Last_OpenB_Cmd THEN
        DoorA_T(IN := FALSE, PT := T#0s);
        DoorB_T(IN := TRUE, PT := T#1s);
    END_IF;
END_IF;

DoorA := DoorA_T.Q;
DoorB := DoorB_T.Q;

Last_OpenA_Cmd := OpenA_Cmd;
Last_OpenB_Cmd := OpenB_Cmd;
END_PROGRAM

