ELSE
    DoorA := FALSE;
END_IF;

IF OpenB_Cmd AND NOT OpenA_Cmd AND NOT DoorB THEN
    DoorB := TRUE;
    DoorA := FALSE;
    DoorBTimer(IN := TRUE, PT := T#2s);
ELSIF OpenB_Cmd AND OpenA_Cmd AND NOT DoorB THEN
    DoorB := TRUE;
    DoorA := FALSE;
    DoorBTimer(IN := TRUE, PT := T#2s);
ELSE
    DoorB := FALSE;
END_IF;

Prev_OpenA_Cmd := OpenA_Cmd;
Prev_OpenB_Cmd := OpenB_Cmd;
END_PROGRAM

