    DoorB := TRUE;
    DoorBTimer(IN := TRUE, PT := T#2s);
ELSIF NOT OpenA_Cmd AND NOT OpenB_Cmd THEN
    IF DoorA THEN
        DoorA := FALSE;
        DoorATimer(IN := FALSE);
    END_IF;
    IF DoorB THEN
        DoorB := FALSE;
        DoorBTimer(IN := FALSE);
