PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartDelay : TON;
END_VAR

StartDelay(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#1s);

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
ELSIF StartDelay.Q THEN
    Running := TRUE;
END_IF;

Conveyor := Running;
END_PROGRAM

