VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT (GuardClosed OR Fault), PT := T#5s);

IF StartPB AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

Conveyor := Running AND SafetyTimer.Q;
END_PROGRAM

PROGRAM conveyor_ctrl
