    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := NOT (GuardClosed OR Fault), PT := T#5s);

CASE
WHEN StopPB THEN
    Running := FALSE;
WHEN StartPB AND GuardClosed AND NOT Fault AND NOT Running THEN
    Running := TRUE;
WHEN SafetyTimer.Q THEN
    Running := FALSE;
END_CASE;

Conveyor := Running;
END_PROGRAM

