    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Alarm : BOOL;
END_VAR

VAR
    TripHeld : BOOL := FALSE;
    ResetTimer : TON;
END_VAR

TripHeld := Trip;

IF Trip THEN
    ResetTimer(IN := TRUE, PT := T#5s);
