PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    GreenTimer, YellowTimer, AllRedTimer : TON;
END_VAR

GreenTimer(IN := TRUE, PT := T#2s);
YellowTimer(IN := TRUE, PT := T#1s);
AllRedTimer(IN := TRUE, PT := T#1s);

CASE State OF
    0: 
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        IF GreenTimer.Q THEN
            State := 1;
        END_IF;

    1: 
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        IF YellowTimer.Q THEN
            State := 2;
        END_IF;

    2: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        IF AllRedTimer.Q THEN
            State := 3;
        END_IF;

    3: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        IF GreenTimer.Q THEN
            State := 4;
        END_IF;

    4: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        IF YellowTimer.Q THEN
            State := 5;
        END_IF;

    5: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        IF AllRedTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    TimerNSGreen, TimerNSYellow, TimerAllRed, TimerEWGreen, TimerEWYellow : TON;
END_VAR

TimerNSGreen(IN := FALSE);
TimerNSYellow(IN := FALSE);
TimerAllRed(IN := FALSE);
TimerEWGreen(IN := FALSE);
TimerEWYellow(IN := FALSE);

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TimerNSGreen(PT := T#2s);
        IF TimerNSGreen.Q THEN
            State := 1;
        END_IF;

    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TimerNSYellow(PT := T#1s);
        IF TimerNSYellow.Q THEN
            State := 2;
        END_IF;

    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TimerAllRed(PT := T#1s);
        IF TimerAllRed.Q THEN
            State := 3;
        END_IF;

    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        TimerEWGreen(PT := T#2s);
        IF TimerEWGreen.Q THEN
            State := 4;
        END_IF;

    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        TimerEWYellow(PT := T#1s);
        IF TimerEWYellow.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TimerAllRed(PT := T#1s);
        IF TimerAllRed.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TNS_G, TNS_Y, TEW_G, TEW_Y, TAllRed : TON;
END_VAR

TNS_G.PT := T#2s;
TNS_Y.PT := T#1s;
TEW_G.PT := T#2s;
TEW_Y.PT := T#1s;
TAllRed.PT := T#1s;

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_G(IN := TRUE);
        TEW_R(IN := TRUE);
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_Y(IN := TRUE);
        TEW_R(IN := TRUE);
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TAllRed(IN := TRUE);
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        TAllRed(IN := TRUE);
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        TAllRed(IN := TRUE);
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TAllRed(IN := TRUE);
END_CASE;

IF TNS_G.Q THEN
    State := 1;
ELSIF TNS_Y.Q THEN
    State := 2;
ELSIF TAllRed.Q THEN
    IF State = 2 THEN
        State := 3;
    ELSE
        State := (State + 1) MOD 6;
    END_IF;
END_IF;

IF TEW_G.Q THEN
    State := 4;
ELSIF TEW_Y.Q THEN
    State := 5;
ELSIF TAllRed.Q THEN
    IF State = 5 THEN
        State := 0;
    ELSE
        State := (State + 1) MOD 6;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TimerNSGreen, TimerNSYellow, TimerAllRed, TimerEWGreen, TimerEWYellow : TON;
END_VAR

TimerNSGreen(IN := State = 0, PT := T#2s);
TimerNSYellow(IN := State = 1, PT := T#1s);
TimerAllRed(IN := State = 2, PT := T#1s);
TimerEWGreen(IN := State = 3, PT := T#2s);
TimerEWYellow(IN := State = 4, PT := T#1s);

CASE State OF
    0: 
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    1: 
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    2: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    3: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
    4: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
    5: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

IF TimerNSGreen.Q THEN State := 1; TimerNSGreen(IN := FALSE); END_IF;
IF TimerNSYellow.Q THEN State := 2; TimerNSYellow(IN := FALSE); END_IF;
IF TimerAllRed.Q THEN State := 3; TimerAllRed(IN := FALSE); END_IF;
IF TimerEWGreen.Q THEN State := 4; TimerEWGreen(IN := FALSE); END_IF;
IF TimerEWYellow.Q THEN State := 5; TimerEWYellow(IN := FALSE); END_IF;
