PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    SafetyTimer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    LastStateChangeTime : TIME := T#0s;
END_VAR

SafetyTimer(IN := NOT EStop, PT := T#1s);

IF SafetyTimer.Q THEN
    IF StartBatch AND EStop THEN
        CASE State OF
            0: -- Idle
                IF Level >= LIQ_MIN THEN
                    State := 1;
                    LastStateChangeTime := SafetyTimer.I;
                END_IF;

            1: -- Fill
                IF Level >= LVL_HIGH THEN
                    State := 2;
                    LastStateChangeTime := SafetyTimer.I;
                ELSE
                    FillValve := TRUE;
                    Heater := FALSE;
                    Agitator := FALSE;
                    DrainValve := FALSE;
                END_IF;

            2: -- Heat
                IF Temp >= TEMP_SET THEN
                    IF TimeDiff(SafetyTimer.I, LastStateChangeTime) >= PT_REACT THEN
                        State := 3;
                        LastStateChangeTime := SafetyTimer.I;
                    END_IF;
                ELSE
                    FillValve := FALSE;
                    Heater := TRUE;
                    Agitator := TRUE;
                    DrainValve := FALSE;
                END_IF;

            3: -- React
                IF Temp >= TEMP_SET THEN
                    IF TimeDiff(SafetyTimer.I, LastStateChangeTime) >= PT_REACT THEN
                        State := 4;
                        LastStateChangeTime := SafetyTimer.I;
                    END_IF;
                ELSE
                    FillValve := FALSE;
                    Heater := TRUE;
                    Agitator := TRUE;
                    DrainValve := FALSE;
                END_IF;

            4: -- Drain
                IF Level <= LVL_LOW THEN
                    State := 0;
                    LastStateChangeTime := SafetyTimer.I;
                ELSE
                    FillValve := FALSE;
                    Heater := FALSE;
                    Agitator := FALSE;
                    DrainValve := TRUE;
                END_IF;
        END_CASE;
    ELSE
        State := 0;
        LastStateChangeTime := SafetyTimer.I;
    END_IF;

    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

PROCEDURE TimeDiff(T1 : TIME, T2 : TIME) : TIME
VAR
    Diff : TIME;
BEGIN
    Diff := T1 - T2;
    IF Diff < T#0s THEN
        Diff := T#0s;
    END_IF;
    TimeDiff := Diff;
END_PROCEDURE;

