        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF NOT EStop THEN
            IF StopPB THEN
                State := 0;
            ELSIF StarTimer.Q THEN
                State := 2;
                DeltaTimer(IN := TRUE, PT := T#3s);
            END_IF;
        ELSE
            State := 0;
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF NOT EStop THEN
            IF StopPB THEN
                State := 0;
            ELSIF DeltaTimer.Q THEN
                State := 0;
            END_IF;
