PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR

VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1: // Pre-purge
        PurgeTimer(IN := TRUE, PT := T#3s);
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    2: // Ignition trial
        IgnitionTimer(IN := TRUE, PT := T#2s);
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame THEN
            State := 0;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    ELSE
        State := 0;
END_CASE;

// Safety checks
IF NOT EStop THEN
    State := 0;
END_IF;

IF State = 1 THEN
    Fuel := FALSE;
END_IF;

IF State IN [2, 3] THEN
    Ignition := FALSE;
END_IF;

IF State <> 1 THEN
    PurgeTimer(IN := FALSE);
END_IF;

IF State <> 2 THEN
    IgnitionTimer(IN := FALSE);
END_IF;

END_PROGRAM

