    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    Timer_C3 : TON;
    Timer_C2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF NOT EStop AND StartPB THEN
            State := 1;
            Timer_C3(IN := TRUE, PT := PT_SEQ);
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := Timer_C3.Q;
        IF Not EStop AND StopPB OR NOT EStop AND NOT Timer_C3.Q THEN
            State := 0;
        ELSIF NOT EStop AND Timer_C3.Q THEN
            State := 2;
            Timer_C2(IN := TRUE, PT := PT_SEQ);
        END_IF;

    2:
        C1 := FALSE;
        C2 := Timer_C2.Q;
        C3 := Timer_C2.Q;
        IF Not EStop AND StopPB OR NOT EStop AND NOT Timer_C2.Q THEN
            State := 0;
        ELSIF NOT EStop AND Timer_C2.Q THEN
            State := 3;
        END_IF;

    3:
        C1 := Timer_C2.Q;
        C2 := Timer_C2.Q;
        C3 := Timer_C2.Q;
        IF Not EStop AND StopPB OR NOT EStop AND NOT Timer_C2.Q THEN
            State := 0;
        END_IF;
END_CASE;

IF NOT EStop THEN
    State := 0;
END_IF;

