    TimerC2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;

    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF EStop OR StopPB THEN
            State := 0;
        ELSIF TimerC3.Q AND NOT EStop THEN
            TimerC3(IN := FALSE);
            TimerC2(IN := TRUE, PT := PT_SEQ);
            State := 2;
        END_IF;

    2:
